const p = await drone.getPlayer();
let placed = 0;
let missing = 0;
for (let dx = 0; dx < 5; dx++) {
  const r = await drone.placeBlock(p.blockX + dx, p.blockY, p.blockZ + 2, 'cobblestone');
  if (r && r.placed) placed++; else missing++;
}
return { placed, missing, hint: missing ? 'Gather cobblestone into the drone inventory first (breakBlock or takeFromPlayer); placeBlock never pulls from chests.' : '' };
